/**
 * Multiplica vector x por matriz W y suma sesgo b, con activación opcional.
 * W tiene forma [n_in x n_out] (columna-mayor de scikit-learn).
 * @param {number[][]} W - Matriz de pesos
 * @param {number[]} b  - Vector de sesgos
 * @param {number[]} x  - Vector de entrada
 * @param {Function|null} activation - Función de activación
 * @returns {number[]}
 */
function _matVec(W, b, x, activation) {
  const nOut = W[0].length;
  const out = new Array(nOut);
  for (let j = 0; j < nOut; j++) {
    let sum = b[j];
    for (let i = 0; i < x.length; i++) sum += W[i][j] * x[i];
    out[j] = activation ? activation(sum) : sum;
  }
  return out;
}

const _relu    = v => Math.max(0, v);
const _sigmoid = v => 1 / (1 + Math.exp(-v));

/**
 * Aplica imputación, escalado estándar y propagación hacia adelante (MLP).
 * @param {number[]} features - Array de 22 atributos clínicos
 * @returns {{ surgery: number, noSurgery: number }} - Probabilidades
 */
function nnPredict(features) {
  const p = NN_PARAMS;

  // 1. Imputar valores faltantes con la mediana de entrenamiento
  let x = features.map((v, i) => (isNaN(v) || v === null) ? p.medians[i] : v);

  // 2. Estandarizar: z = (x - mean) / std
  x = x.map((v, i) => (v - p.mean[i]) / p.scale[i]);

  // 3. Propagación hacia adelante
  // Capa oculta 1: 22 → 64 (ReLU)
  x = _matVec(p.weights[0], p.biases[0], x, _relu);
  // Capa oculta 2: 64 → 32 (ReLU)
  x = _matVec(p.weights[1], p.biases[1], x, _relu);
  // Capa de salida:  32 → 1  (sin activación, se aplica sigmoid después)
  const logit = _matVec(p.weights[2], p.biases[2], x, null)[0];

  const probSurgery = _sigmoid(logit);

  return {
    surgery: probSurgery,
    noSurgery: 1 - probSurgery
  };
}
